import{_ as o,c as s,o as e,ag as r}from"./chunks/framework.Cycwnjj0.js";const n="/assets/adding-new-post-from-wordpress-dashboard.CJPEPvdn.webp",a="/assets/select-classic-editor-by-clicking-plus-icon.Al2CYzrI.webp",i="/assets/add-media-option-from-the-classic-editor.dP_S4wwm.webp",l="/assets/5-major-options-under-azonpress.DK68b4qS.webp",c="/assets/product-templates.Dn6mJ349.webp",g="/assets/product-elements.C82EodUX.webp",d="/assets/best-seller.CVGsRqrY.webp",p="/assets/comparison-tables.CmbRzHgM.webp",h="/assets/products-tables.BQ8rGg1W.webp",k=JSON.parse('{"title":"How to use AzonPress with Classic Editor (Gutenberg Block)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started/how-to-use-azonpress-with-classic-editor-gutenberg-block.md","filePath":"guide/getting-started/how-to-use-azonpress-with-classic-editor-gutenberg-block.md"}'),u={name:"guide/getting-started/how-to-use-azonpress-with-classic-editor-gutenberg-block.md"};function m(b,t,w,y,f,P){return e(),s("div",null,[...t[0]||(t[0]=[r('<h1 id="how-to-use-azonpress-with-classic-editor-gutenberg-block" tabindex="-1">How to use AzonPress with Classic Editor (Gutenberg Block) <a class="header-anchor" href="#how-to-use-azonpress-with-classic-editor-gutenberg-block" aria-label="Permalink to &quot;How to use AzonPress with Classic Editor (Gutenberg Block)&quot;">​</a></h1><p>AzonPress is a standard Amazon Associate plugin for WordPress. This plugin offers an advanced feature that enables you to <strong>display Amazon Products</strong> using <strong>Classic Editor</strong>. This article will guide you through the process of using AzonPress with Classic Editor of WordPress.</p><h2 id="use-azonpress-with-classic-editor" tabindex="-1">Use AzonPress With Classic Editor <a class="header-anchor" href="#use-azonpress-with-classic-editor" aria-label="Permalink to &quot;Use AzonPress With Classic Editor&quot;">​</a></h2><p>To learn how to use AzonPress with Classic WordPress Editor, follow the steps with the screenshots below –</p><p>From your <strong>WordPress Dashboard</strong>, go to the desired <strong>Posts/Pages</strong> where you want to display your Amazon Products. Or, you can create a new <strong>Post/Page</strong> for showcasing the products on that specific post/page.</p><p><strong>For example</strong>, here, I am creating a new <strong>Post</strong> to display the <strong>Amazon Products</strong> using <strong>Classic Editor.</strong></p><p>First, go to the <strong>Posts</strong> from <strong>WordPress Dashboard</strong> &amp; click on the <strong>Add New Post</strong>.</p><p><img src="'+n+'" alt="Adding new post from WordPress dashboard"></p><p>Then, <strong>add</strong> a suitable <strong>title</strong> for the post you want to work on and click over the <strong>Plus (+) icon</strong> of the Gutenberg editor &amp; select the <strong>Classic</strong> WordPress editor.</p><p><img src="'+a+'" alt="Select Classic Editor by clicking Plus Icon"></p><p>Next, click the <strong>Add Media</strong> option from the <strong>classic editor</strong> bar, and a pop-up window appears with a couple of options.</p><p><img src="'+i+'" alt="Add media option from the classic editor"></p><p>Press <strong>AzonPress</strong> from the left sidebar and you will get <strong>Five</strong> different <strong>Tabs</strong> with various <strong>settings options</strong> for <strong>showcasing</strong> your <strong>Amazon products</strong>. These are –</p><ol><li>Product Templates</li><li>Product Elements</li><li>Bestseller Lists</li><li>Comparison Tables</li><li>Product Tables</li></ol><p>But, to get all these tabs, you need to configure the Amazon API key into the AzonPress plugin first. To learn how you can do it, read this <a href="/guide/configuring-amazon-api/configure-amazon-api.html">Documentation</a>.</p><p><img src="'+l+'" alt="5 major options under AzonPress"></p><p><strong>A detailed explanation of these five settings options mentioned above is given below:</strong></p><h3 id="product-templates" tabindex="-1">Product Templates <a class="header-anchor" href="#product-templates" aria-label="Permalink to &quot;Product Templates&quot;">​</a></h3><p>Under the <strong>Product Templates</strong> tab, you will find various types of settings options which are briefly explained with the screenshot below –</p><p><strong>Search Bar:</strong> Now you can look for any kind of product you want in the <strong>search box</strong> of the Product Templates tab. These products will be displayed right below the search box.</p><p><strong>Select All:</strong> You can choose what products you wish to show on your page by clicking the specific product or you can show all of them by just clicking the <strong>Select All</strong> button.</p><p><strong>Load more from next page:</strong> If you want to see more products related to your search just press the <strong>load more from next page</strong> button.</p><p><strong>Select Layout:</strong> It offers six types of layouts for presenting your products. These are <strong>Grid</strong>, <strong>Box</strong>, <strong>List</strong>, <strong>Table</strong>, <strong>Widget</strong>, and <strong>Widget Small</strong>. Select any layout by clicking the checkbox that suits your needs.</p><p><strong>Select number of column:</strong> This option appears only under Grid Layout where you need to select from 1 to 4 how many columns you want for showcasing your products. And, you can select this easily from the dropdown list by clicking the arrow icon.</p><p><strong>Insert Shortcode:</strong> Once you are done, you can click the <strong>Insert Shortcode</strong> button and the shortcode will be automatically embedded in your post. Then, <strong>publish</strong> it and your Amazon Products will appear on your site under that post.</p><p>If you want to <strong>showcase the same products</strong> in <strong>another post/s</strong>, you can also do it simply by <strong>copying</strong> the <strong>Shortcode</strong> visible <strong>right before</strong> the <strong>Insert Shortcode</strong> button and <strong>pasting</strong> it into the desired post/s.</p><p><img src="'+c+'" alt="Product Templates"></p><h3 id="product-elements" tabindex="-1">Product Elements <a class="header-anchor" href="#product-elements" aria-label="Permalink to &quot;Product Elements&quot;">​</a></h3><p>Product Elements will give you the <strong>Text Link</strong>, <strong>Product Image Link</strong>, <strong>CTA Link</strong>, and <strong>Feature Box</strong> about some products that you have searched through the search bar.</p><p>To learn about the Product Elements in detail, read this <a href="/guide/available-products-templates/product-elements.html">Documentation</a>.</p><p><img src="'+g+'" alt="Product Elements"></p><h3 id="bestseller-lists" tabindex="-1">BestSeller Lists <a class="header-anchor" href="#bestseller-lists" aria-label="Permalink to &quot;BestSeller Lists&quot;">​</a></h3><p>In this Bestseller Lists option, you will find different settings options. These are:</p><ul><li><strong>Select BestSeller Category</strong>: Here, you just need to <strong>select</strong> the <strong>Category</strong> of the <strong>bestseller product</strong>.</li><li><strong>Your Product Search Term</strong>: In this field, give the <strong>search term</strong> to make your search more specific.</li><li><strong>Product Limit</strong>: You can also <strong>set the limit</strong> here on how many products you want to show on your product page.</li><li><strong>Select Layout</strong>: Under this option, you will get some templates for your product showing. These are <strong>Grid</strong>, <strong>Box</strong>, <strong>List</strong>, <strong>Table</strong>, <strong>Widget</strong>, and <strong>Widget Small</strong>.</li><li><strong>Insert Shortcode</strong>: Finally, hit the <strong>Insert Shortcode</strong> button to showcase the BestSeller Amazon Products in your post.</li></ul><p><img src="'+d+'" alt="Best Seller"></p><h3 id="comparison-table" tabindex="-1">Comparison Table <a class="header-anchor" href="#comparison-table" aria-label="Permalink to &quot;Comparison Table&quot;">​</a></h3><p>On this tab, you can add your existing comparison tables by clicking the <strong>Insert Shortcode</strong> button and searching for tables using the <strong>search bar</strong>.</p><p>If you don&#39;t have any existing comparison tables, read this <a href="/guide/amazon-comparison-tables/how-to-create-an-amazon-comparison-table.html">Documentation</a> to learn how to create comparison tables.</p><p><img src="'+p+'" alt="Comparison Tables"></p><h3 id="product-table" tabindex="-1">Product Table <a class="header-anchor" href="#product-table" aria-label="Permalink to &quot;Product Table&quot;">​</a></h3><p>The last tab will allow you to add your existing product tables by clicking the <strong>Insert Shortcode</strong> button and searching for tables using the <strong>search bar</strong>.</p><p>If you don&#39;t have any existing product tables, read this <a href="/guide/product-tables-module/how-to-create-an-amazon-product-table.html">Documentation</a> to learn how to create product tables.</p><p><img src="'+h+'" alt="Products Tables"></p><p>If you have any further questions, concerns, or suggestions, please do not hesitate to contact our support team. Thank you.</p><hr>',45)])])}const _=o(u,[["render",m]]);export{k as __pageData,_ as default};
